    background-color: #000000cc;
}

.Shop1EnhanceWindow {
    horizontal-align: center;
    vertical-align: center;
    flow-children: down;
    padding: 16px 20px;
    background-color: gradient(linear, 0% 0%, 0% 100%, from(#c58760f0), to(#643c19f0));
    border: 0px solid #6b6b6b;
    border-radius: 10px;
