}

.Shop1EnhanceTitleBar {
    width: 100%;
    horizontal-align: center;
    margin-bottom: 12px;
}

.Shop1EnhanceTitle {
    horizontal-align: center;
    font-size: 32px;
    font-weight: bold;
    color: #ffe250;
    text-shadow: 0px 0px 4px 3 #000000;
}

.Shop1EnhanceCardRow {
    flow-children: right;
    horizontal-align: center;
    margin-bottom: 12px;
}

.Shop1EnhanceCard {
    width: 240px;
    height: 400px;
    margin: 0 8px;
    padding: 0 10px 12px 10px;
    background-color: #faf2dbdd;
