@define selection_window_width: 60%;
@define selection_window_height: 60%;

.Hidden {
    visibility: collapse;
    opacity: 0.0;
}

.SelectionSpecialRoot {
    width: 100%;
    height: 100%;
    opacity: 0.0;
    transition-property: opacity;
    transition-duration: 0.25s;
}

.SelectionSpecialRoot.Show {
    opacity: 1.0;
}

.SelectionSpecialMask {
    width: 100%;
    height: 100%;
    background-color: #000c;
}

/* 三功能区：左标题栏 / 中央内容 / 右侧信息栏 */
.SelectionSpecialWindow {
    width: selection_window_width;
    height: selection_window_height;
    horizontal-align: center;
    vertical-align: center;
    flow-children: right;

    background-color: gradient(linear, 0% 0%, 100% 100%, from(#20232aff), to(#101318ff));
    border: 2px solid #8a6c3b;
    border-radius: 8px;
    box-shadow: #000000ee 0px 0px 16px 0px;

    pre-transform-scale2d: 0.95;
    transition-property: pre-transform-scale2d, opacity;
    transition-duration: 0.2s;
    transition-timing-function: ease-out;
}

.SelectionSpecialRoot.Show .SelectionSpecialWindow {
    pre-transform-scale2d: 1.0;
}

/* 功能区 1：左侧标题栏 */
.SelectionSpecialLeftBar {
    width: 14%;
    height: 100%;
    padding: 18px 10px;
    background-color: gradient(linear, 0% 0%, 0% 100%, from(#14171dee), to(#0f1116ee));
    border-right: 1px solid #3a2b1a;
}

.SelectionSpecialTitle {
    font-size: 30px;
    font-weight: bold;
    color: #ffe6b3;
    text-shadow: 1px 1px 3px #000000;
    vertical-align: top;
}

/* 功能区 2：中央内容区（严格在上下边界内工作） */
.SelectionSpecialContent {
    width: fill-parent-flow(1);
    height: 100%;
    padding: 18px 12px;
    flow-children: down;
}

/* 功能区 3：右侧信息栏（倒计时在上，放弃在下，中间 Spacer 吃剩余） */
.SelectionSpecialRightBar {
    width: 14%;
    height: 100%;
    padding: 18px 10px;
    flow-children: down;
    background-color: gradient(linear, 0% 0%, 0% 100%, from(#14171dee), to(#0f1116ee));
    border-left: 1px solid #3a2b1a;
}

.SelectionSpecialTimerBox {
    width: 100%;
    flow-children: right;
    horizontal-align: center;
}

.SelectionSpecialTimerLabel {
    font-size: 18px;
    color: #cccccc;
    vertical-align: center;
    margin-right: 6px;
}

.SelectionSpecialTimerValue {
    font-size: 26px;
    font-weight: bold;
    color: #ffdf5a;
    text-shadow: 1px 1px 3px #000000;
    vertical-align: center;
}

.SelectionSpecialRightBarSpacer {
    width: 100%;
    height: fill-parent-flow(1);
}

.SelectionSpecialModePick {
    width: 100%;
    height: 100%;
    flow-children: none;
}

/* 关键：卡牌区域必须吃“中央剩余空间”，不能写死 100% 去越界 */
.SelectionSpecialCenterWrapper {
    width: 100%;
    height: fill-parent-flow(1);
    horizontal-align: center;
    vertical-align: center;
    flow-children: down;
}

/* =========================
   Pick 卡牌行：横向饱满 + 不越界
   ========================= */

/* 卡牌行本身只吃中间剩余高度（上下硬边界由整体布局保证） */
.SelectionSpecialCardRow {
    width: 100%;
    height: fill-parent-flow(1);
    flow-children: right;

    padding-left: 10px;
    padding-right: 10px;

    horizontal-align: center;
    vertical-align: center;
}

/* Slot 只当壳：不参与横向等分（避免 double fill-parent-flow 稀释宽度） */
.SelectionSpecialCardSlot {
    width: fill-parent-flow(1);
    height: 100%;
    flow-children: none;

    padding-left: 10px;
    padding-right: 10px;
}


.SelectionSpecialIconButton {
    width: 72px;
    height: 72px;
    margin-left: 12px;
    margin-right: 12px;
    background-color: #000000aa;
    border: 1px solid #555555;
    border-radius: 4px;
    transition-property: brightness, pre-transform-scale2d, border;
    transition-duration: 0.08s;
    transition-timing-function: ease-out;
}

.SelectionSpecialIconButton:hover {
    brightness: 1.6;
    pre-transform-scale2d: 1.05;
    border: 1px solid #d8a040;
}

.SelectionSpecialIconButton.Disabled {
